import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import {
  WebAuthnFinishReq,
  WebAuthnFinishRes,
  WebAuthnFirstStepReq,
  WebAuthnFirstStepRes,
} from '~/entities/biometric/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

// 생체인증 서버 등록 요청
export const webAuthnRegisterOptions = ({ username, displayname }: WebAuthnFirstStepReq) => {
  return resultify(axios.post<WebAuthnFirstStepRes>(API_URLS.registerLbdyUse(''), { username, displayname }));
};

// 생체인증 서버 등록 요청 완료
export const webAuthnRegister = (params: WebAuthnFinishReq) => {
  return resultify(axios.post<WebAuthnFinishRes>(API_URLS.registerLbdyUse('finish'), params));
};

export const useWebAuthnRegisterOptionsMutation = (
  options?: MutationOptions<WebAuthnFirstStepReq, CBDCAxiosError, WebAuthnFirstStepRes>,
) => {
  const mutation = useMutation<WebAuthnFirstStepRes, CBDCAxiosError, WebAuthnFirstStepReq>({
    ...options,
    mutationFn: webAuthnRegisterOptions,
  });

  return {
    ...mutation,
  };
};

export const useWebAuthnRegistrationMutation = (
  options?: MutationOptions<WebAuthnFinishReq, CBDCAxiosError, WebAuthnFinishRes>,
) => {
  const mutation = useMutation<WebAuthnFinishRes, CBDCAxiosError, WebAuthnFinishReq>({
    ...options,
    mutationFn: webAuthnRegister,
  });

  return {
    ...mutation,
  };
};
